$(document).ready(function(){
	getcamSettings();
	$("#logout").click(function(){ 

		Swal.fire({
		title: 'Are you sure?',
		text: "Logout!",
		icon: 'warning',
		showCancelButton: true,
		confirmButtonColor: '#3085d6',
		cancelButtonColor: '#d33',
		confirmButtonText: 'Logout!'
		}).then((result) => {
		if (result.isConfirmed) { 
			$.post("/admin/router/router.php",{request: "logout"}, function(data){
				location.reload();
			});
		}
		})
	})
	get_session();
	const cameraMenu = document.getElementById('cameraMenu');
    const toggleIcon = document.querySelector('.toggle-icon');

    cameraMenu.addEventListener('show.bs.collapse', function () {
        toggleIcon.classList.add('rotate');
    });

    cameraMenu.addEventListener('hide.bs.collapse', function () {
        toggleIcon.classList.remove('rotate');
    });
})

document.addEventListener('contextmenu', function(e) {
	e.preventDefault();  
});

// Disable F5 (Refresh)
document.addEventListener('keydown', function(e) {
	// Disable F12 (Developer Tools)
	if (e.key === 'F12') {
		e.preventDefault(); 
	}
});


function get_session()
{
	$.post("/admin/router/router.php",{request: "get_session"}, function(data){  
	});
}

function getcamSettings()
{
	$.post("/admin/router/router.php",{request: "getcamSettings"}, function(data){   
		if(data == "N")
		{
			$('a[href="#cameraMenu"]').css({
				'pointer-events': 'none',
				'opacity': '0.5',
				'cursor': 'not-allowed'
			});
		}
	});
}

 
